10	    match f {
11	        V::Func(fun) => (fun.f)(a),
12	        V::Bound(b) => {
13	            let mut a = a;
14	            prepend(&mut a.p, b.0.clone());
15	            call(&b.1, a)
16	        }
17	        V::BMeth(b) => call_method(&b.0, b.1, a),
18	        V::Class(c) => instantiate(c, a),
19	        V::Obj(o) => match o.cls.lookup("__call__") {
20	            Some(m) => {
21	                let mut a = a;
22	                prepend(&mut a.p, f.clone());
23	                call(&m, a)
