25	            None => type_err(format!("'{}' object is not callable", tn(f))),
26	        },
27	        V::Ext(x) => match x.method(f, "__call__", &mut { a }) {
28	            Some(r) => r,
29	            None => type_err(format!("'{}' object is not callable", tn(f))),
30	        },
31	        _ => type_err(format!("'{}' object is not callable", tn(f))),
